from html import escape

from fastapi.responses import HTMLResponse

from .schemas import BotCatalogItem


def _page(title: str, body: str) -> HTMLResponse:
    return HTMLResponse(f"""<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" type="image/png" href="/static/brand/icon-1-black.png"><link rel="apple-touch-icon" href="/static/brand/icon-1-black.png"><title>{escape(title)}</title><style>
    :root {{ color-scheme:dark; --bg:#000; --panel:#0b0b0b; --panel2:#151515; --border:#666; --text:#fff; --muted:#a6a6a6; --green:#41d392; --red:#ff6b81; --yellow:#f6c667; }}
    * {{ box-sizing:border-box; }} body {{ margin:0; font-family:Inter,Arial,sans-serif; color:var(--text); background:var(--bg); }} main {{ max-width:1240px; margin:auto; padding:36px 20px 48px; }} h1,h2,p {{ margin-top:0; }} .muted {{ color:var(--muted); }} .header {{ display:flex; align-items:flex-start; justify-content:space-between; gap:16px; margin-bottom:28px; }} button {{ font:inherit; cursor:pointer; }} .link-button {{ color:var(--muted); background:transparent; border:0; padding:0; }} .panel,.card {{ background:var(--panel); border:1px solid var(--border); border-radius:10px; }} .brand {{ display:inline-flex; width:max-content; }} .brand img {{ display:block; width:118px; height:auto; }} .brand-compact img {{ width:72px; }}
    @media(max-width:640px) {{ main {{ padding:24px 16px; }} .header {{ flex-direction:column; }} }}
    </style><script src="/static/security.js"></script></head><body>{body}</body></html>""")


def render_login_page(error: str | None = None, status_code: int = 200) -> HTMLResponse:
    error_html = f'<p class="error">{escape(error)}</p>' if error else ""
    response = _page("2Lotus | Estratégias", f"""<main class="login"><section class="panel"><img class="login-logo" src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"><h1>Estratégias</h1><p class="muted">Acesse os testes e indicadores de performance.</p>{error_html}<form method="post" action="/login"><label>Senha<input type="password" name="password" autocomplete="current-password" required autofocus></label><button type="submit">Entrar</button></form></section></main><style>
    .login {{ min-height:100vh; display:grid; place-items:center; padding:20px; }} .login .panel {{ width:min(100%,400px); padding:30px; }} .login-logo {{ display:block; width:185px; height:auto; margin:0 auto 26px; }} .login label {{ display:grid; gap:8px; margin:24px 0 14px; font-size:14px; }} .login input {{ border:1px solid var(--border); border-radius:8px; background:#000; color:var(--text); padding:12px; font:inherit; }} .login button {{ width:100%; border:1px solid #fff; border-radius:8px; background:#fff; color:#000; padding:12px; font-weight:700; }} .error {{ color:var(--red); font-size:14px; }}
    </style>""")
    response.status_code = status_code
    return response


def render_catalog_page(active_bots: list[BotCatalogItem], archived_bots: list[BotCatalogItem] | None = None) -> HTMLResponse:

    def render_cards(bots: list[BotCatalogItem], *, archived: bool) -> str:
        if not bots:
            return '<p class="muted empty-state">Nenhuma estratégia nesta seção.</p>'
        badge = '<span class="status-badge">Arquivada</span>' if archived else '<span class="status-badge active">Ativa</span>'
        action = "Ver histórico →" if archived else "Ver resultados →"
        return "".join(
            f'''<a class="bot card" href="/bots/{escape(bot.id)}"><div class="card-meta"><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)}</p>{badge}</div><h2>{escape(bot.name)}</h2><p class="muted">{escape(bot.description)}</p><strong>{action}</strong></a>'''
            for bot in bots
        )

    active_cards = render_cards(active_bots, archived=False)
    return _page("2Lotus | Estratégias", f"""<main><header class="header"><div><a class="brand" href="/bots" aria-label="2Lotus"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><h1>Estratégias</h1><p class="muted">Acompanhe as seis estratégias selecionadas para shadow e validação.</p></div><div class="header-actions"><a href="/operations">Saúde operacional</a><a href="/growth-simulator">Simular crescimento</a><a href="/compare">Comparar estratégias</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section>
      <section class="panel equity-panel"><div class="equity-heading"><div><p class="eyebrow">Backtest de 1 ano</p><h2>Desempenho acumulado das estratégias ativas</h2><p class="muted">XAU/USD · M5 · PnL acumulado simulado em USD</p></div><p class="muted" id="equity-status">Carregando curvas...</p></div><div id="equity-empty" class="muted" hidden></div><svg id="equity-chart" viewBox="0 0 1100 420" role="img" aria-label="Desempenho acumulado das estratégias ativas"></svg><div id="equity-legend" class="equity-legend"></div></section>
      <div class="section-heading"><div><p class="eyebrow">Em acompanhamento</p><h2>Estratégias ativas</h2></div><p class="muted">{len(active_bots)} estratégias</p></div><section class="grid">{active_cards}</section>
    </section></main><style>
    .header-actions {{ display:flex; gap:16px; align-items:center; }} .header-actions a {{ color:var(--text); }} .catalog-tabs {{ display:inline-flex; gap:4px; padding:4px; margin-bottom:22px; border:1px solid var(--border); border-radius:10px; background:var(--panel); }} .catalog-tabs button {{ display:flex; align-items:center; gap:9px; border:0; border-radius:7px; padding:10px 16px; background:transparent; color:var(--muted); font-weight:700; }} .catalog-tabs button[aria-selected="true"] {{ background:#fff; color:#000; }} .catalog-tabs span {{ min-width:22px; padding:2px 6px; border-radius:999px; background:rgba(127,127,127,.2); font-size:12px; text-align:center; }}
    .equity-panel {{ padding:20px; margin-bottom:28px; }} .equity-heading,.section-heading {{ display:flex; align-items:flex-start; justify-content:space-between; gap:18px; }} .equity-heading h2 {{ margin-bottom:6px; }} .eyebrow {{ margin-bottom:6px; color:var(--green); font-size:12px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; }} #equity-chart {{ width:100%; min-height:320px; margin-top:8px; }} .equity-legend {{ display:flex; flex-wrap:wrap; gap:9px 16px; padding-top:12px; border-top:1px solid rgba(255,255,255,.14); }} .legend-item {{ display:inline-flex; align-items:center; gap:7px; color:var(--muted); font-size:12px; }} .legend-item i {{ width:18px; height:3px; border-radius:999px; }} .section-heading {{ margin-bottom:14px; }} .section-heading h2 {{ margin-bottom:0; }}
    .grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(260px,1fr)); gap:16px; }} .bot {{ min-height:220px; display:flex; flex-direction:column; align-items:flex-start; padding:22px; color:var(--text); text-decoration:none; }} .bot h2,.bot p {{ margin-bottom:12px; }} .bot strong {{ color:var(--green); margin-top:auto; }} .card-meta {{ width:100%; display:flex; justify-content:space-between; gap:12px; align-items:flex-start; }} .status-badge {{ padding:4px 8px; border:1px solid #555; border-radius:999px; color:var(--muted); font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.05em; }} .status-badge.active {{ color:var(--green); border-color:rgba(65,211,146,.45); }} .archive-note {{ padding:22px; margin-bottom:18px; border-left:3px solid var(--yellow); }} .archive-note .eyebrow {{ color:var(--yellow); }} .archive-note p:last-child {{ max-width:820px; margin-bottom:0; line-height:1.55; }} .empty-state {{ grid-column:1/-1; padding:24px 0; }}
    @media(max-width:720px) {{ .equity-heading,.section-heading {{ flex-direction:column; }} #equity-chart {{ min-height:250px; }} }}
    </style><script>
    const palette=['#41d392','#62a8ff','#f6c667','#ff6b81','#b78cff','#52d8e8','#ff9f43'];
    const usd=value=>new Intl.NumberFormat('pt-BR',{{style:'currency',currency:'USD',maximumFractionDigits:0}}).format(value||0);
    function renderEquity(data) {{
      const svg=document.getElementById('equity-chart'), empty=document.getElementById('equity-empty'), legend=document.getElementById('equity-legend');
      const usable=(data.series||[]).filter(item=>item.points&&item.points.length);
      if(!usable.length) {{ svg.hidden=true; empty.hidden=false; empty.textContent='O backtest consolidado ainda não foi carregado para este ativo.'; legend.innerHTML=''; return; }}
      svg.hidden=false; empty.hidden=true; const W=1100,H=420,L=78,R=22,T=22,B=48;
      const timestamps=usable.flatMap(item=>item.points.map(point=>+new Date(point.day+'T00:00:00Z'))), values=[0,...usable.flatMap(item=>item.points.map(point=>+point.cumulative_pnl))];
      const minX=Math.min(...timestamps),maxX=Math.max(...timestamps),rawMin=Math.min(...values),rawMax=Math.max(...values),padding=Math.max((rawMax-rawMin)*.12,10),minY=rawMin-padding,maxY=rawMax+padding;
      const x=value=>L+(value-minX)*(W-L-R)/Math.max(maxX-minX,1), y=value=>T+(maxY-value)*(H-T-B)/Math.max(maxY-minY,1);
      const grid=[0,.25,.5,.75,1].map(ratio=>{{const value=maxY-(maxY-minY)*ratio,yy=y(value);return `<line x1="${{L}}" x2="${{W-R}}" y1="${{yy}}" y2="${{yy}}" stroke="#292929"/><text x="${{L-10}}" y="${{yy+4}}" fill="#a6a6a6" text-anchor="end" font-size="12">${{usd(value)}}</text>`;}}).join('');
      const zero=minY<=0&&maxY>=0?`<line x1="${{L}}" x2="${{W-R}}" y1="${{y(0)}}" y2="${{y(0)}}" stroke="#777" stroke-dasharray="5 5"/>`:'';
      const lines=usable.map((item,index)=>{{const color=palette[index%palette.length],points=item.points.map(point=>`${{x(+new Date(point.day+'T00:00:00Z')).toFixed(1)}},${{y(+point.cumulative_pnl).toFixed(1)}}`).join(' ');return `<polyline points="${{points}}" fill="none" stroke="${{color}}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><title>${{item.name}}: ${{usd(item.summary.net_pnl)}}</title></polyline>`;}}).join('');
      const dateLabel=value=>new Date(value).toLocaleDateString('pt-BR',{{month:'short',year:'2-digit',timeZone:'UTC'}}); const xLabels=[0,.25,.5,.75,1].map(ratio=>{{const value=minX+(maxX-minX)*ratio;return `<text x="${{x(value)}}" y="${{H-15}}" fill="#a6a6a6" text-anchor="middle" font-size="12">${{dateLabel(value)}}</text>`;}}).join('');
      svg.innerHTML=grid+zero+lines+xLabels; legend.innerHTML=usable.map((item,index)=>`<span class="legend-item"><i style="background:${{palette[index%palette.length]}}"></i>${{escapeHtml(item.name.replace(' · EUR/USD',''))}} · ${{usd(item.summary.net_pnl)}}</span>`).join('');
    }}
    async function loadActiveEquity() {{
      try {{ const response=await fetch('/api/equity-comparison?symbol=XAUUSD&days=365'); if(!response.ok) throw new Error('Não foi possível carregar a comparação.'); const data=await response.json(); renderEquity(data); document.getElementById('equity-status').textContent=data.series.length+' curvas · '+data.period_days+' dias'+(data.missing_bot_ids.length?' · '+data.missing_bot_ids.length+' pendentes':''); }} catch(error) {{ document.getElementById('equity-status').textContent=error.message; renderEquity({{series:[]}}); }}
    }}
    loadActiveEquity();
    </script>""")


def _render_growth_simulator_page_legacy() -> HTMLResponse:
    return _page("2Lotus | Simulador de crescimento", """<main><header class="header"><div><a class="brand brand-compact" href="/bots" aria-label="2Lotus"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><p class="eyebrow">Happy Gold + Portfólio 7/6 · 100/100</p><h1>Simulador de crescimento</h1><p class="muted">Reaplique as 802 operações do replay anual com capital e risco personalizados.</p></div><div class="actions"><a href="/bots/bot-16">Ver estratégia</a><a href="/bots">Estratégias</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section class="panel controls"><form id="simulation-form"><label>Capital inicial (USD)<input id="initial-balance" name="initial_balance" type="number" min="100" max="100000000" step="100" value="10000" required></label><label>Risco-base por operação (%)<input id="risk" name="risk_per_trade_pct" type="number" min="0.01" max="10" step="0.01" value="0.25" required></label><button type="submit">Simular curva</button></form><p class="muted">O risco é recalculado sobre o saldo antes de cada operação. A sequência de entradas e os resultados em R permanecem iguais ao backtest.</p></section>
    <section class="cards"><article class="card"><p class="muted">Saldo final</p><strong id="final-balance">-</strong><span id="initial-label">-</span></article><article class="card"><p class="muted">PnL projetado</p><strong id="net-pnl">-</strong><span id="return-pct">-</span></article><article class="card"><p class="muted">Drawdown máximo</p><strong id="drawdown">-</strong><span id="drawdown-pct">-</span></article><article class="card"><p class="muted">Operações simuladas</p><strong id="trades">-</strong><span id="period">-</span></article></section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Curva de saldo</h2><p class="muted">Referência: US$ 10.000 e risco de 0,25% · Simulação: valores personalizados</p></div><p class="muted" id="status">Carregando...</p></div><div id="chart-empty" class="muted" hidden></div><svg id="growth-chart" viewBox="0 0 1100 440" role="img" aria-label="Curva simulada de crescimento"></svg><div class="legend"><span><i class="reference"></i>Referência</span><span><i class="simulation"></i>Simulação personalizada</span></div></section>
    <section class="panel warning"><strong>Importante</strong><p class="muted">Esta é uma projeção matemática sobre o histórico já observado. Ela não prevê resultados futuros e não considera mudanças de liquidez, slippage ou capacidade operacional causadas por volumes maiores.</p></section></main><style>
    .eyebrow { margin:0 0 7px; color:var(--green); font-size:12px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; } .actions { display:flex; gap:14px; align-items:flex-start; flex-wrap:wrap; } .actions a { color:var(--text); } .controls { padding:20px; margin-bottom:18px; } .controls form { display:grid; grid-template-columns:repeat(2,minmax(180px,260px)) auto; gap:14px; align-items:end; } label { display:grid; gap:7px; color:var(--muted); font-size:13px; font-weight:700; } input { width:100%; padding:11px 12px; color:var(--text); background:#000; border:1px solid var(--border); border-radius:7px; font:inherit; } input:focus { outline:2px solid rgba(65,211,146,.35); border-color:var(--green); } .controls button { padding:11px 18px; border:1px solid #fff; border-radius:7px; color:#000; background:#fff; font-weight:800; } .controls p { margin:14px 0 0; line-height:1.5; } .cards { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; margin-bottom:18px; } .card { padding:18px; } .card strong { display:block; margin-bottom:8px; font-size:26px; } .card span { color:var(--muted); font-size:13px; } .green { color:var(--green); } .red { color:var(--red); } .chart-panel { padding:20px; margin-bottom:18px; } .chart-heading { display:flex; justify-content:space-between; gap:18px; } .chart-heading h2 { margin-bottom:6px; } #growth-chart { width:100%; min-height:330px; margin-top:8px; } .legend { display:flex; gap:20px; padding-top:12px; border-top:1px solid rgba(255,255,255,.14); color:var(--muted); font-size:13px; } .legend span { display:flex; align-items:center; gap:8px; } .legend i { display:block; width:22px; height:3px; border-radius:999px; } .legend .reference { background:#777; } .legend .simulation { background:var(--green); } .warning { padding:18px; border-left:3px solid var(--yellow); } .warning p { margin:7px 0 0; line-height:1.55; } @media(max-width:850px) { .cards { grid-template-columns:repeat(2,1fr); } .controls form { grid-template-columns:1fr 1fr; } .controls button { grid-column:1/-1; } } @media(max-width:560px) { .cards,.controls form { grid-template-columns:1fr; } .controls button { grid-column:auto; } .chart-heading,.actions { flex-direction:column; } #growth-chart { min-height:260px; } }
    </style><script>
    const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(value||0); const pct=value=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0)+'%';
    function renderChart(data) { const svg=document.getElementById('growth-chart'), empty=document.getElementById('chart-empty'), series=[{...data.reference,color:'#777'},{...data.simulation,color:'#41d392'}].filter(item=>item.points.length); if(!series.length){svg.hidden=true;empty.hidden=false;empty.textContent='Não há operações para simular.';return;} svg.hidden=false;empty.hidden=true; const W=1100,H=440,L=86,R=22,T=22,B=48; const times=series.flatMap(item=>item.points.map(p=>+new Date(p.day+'T00:00:00Z'))), balances=series.flatMap(item=>item.points.map(p=>+p.balance)); const minX=Math.min(...times),maxX=Math.max(...times),rawMin=Math.min(...balances),rawMax=Math.max(...balances),pad=Math.max((rawMax-rawMin)*.12,100),minY=Math.max(0,rawMin-pad),maxY=rawMax+pad; const x=v=>L+(v-minX)*(W-L-R)/Math.max(maxX-minX,1),y=v=>T+(maxY-v)*(H-T-B)/Math.max(maxY-minY,1); const grid=[0,.25,.5,.75,1].map(r=>{const value=maxY-(maxY-minY)*r,yy=y(value);return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#292929"/><text x="${L-9}" y="${yy+4}" text-anchor="end" fill="#999" font-size="11">${money(value)}</text>`}).join(''); const paths=series.map(item=>{const d=item.points.map((p,i)=>`${i?'L':'M'} ${x(+new Date(p.day+'T00:00:00Z')).toFixed(1)} ${y(+p.balance).toFixed(1)}`).join(' '); const last=item.points.at(-1); return `<path d="${d}" fill="none" stroke="${item.color}" stroke-width="${item.label==='Simulação'?4:2}" stroke-linejoin="round"/><circle cx="${x(+new Date(last.day+'T00:00:00Z'))}" cy="${y(+last.balance)}" r="5" fill="${item.color}"><title>${item.label}: ${money(last.balance)}</title></circle>`}).join(''); const labels=`<text x="${L}" y="${H-12}" fill="#999" font-size="11">${new Date(minX).toLocaleDateString('pt-BR')}</text><text x="${W-R}" y="${H-12}" text-anchor="end" fill="#999" font-size="11">${new Date(maxX).toLocaleDateString('pt-BR')}</text>`; svg.innerHTML=grid+paths+labels; }
    function render(data) { const s=data.simulation; document.getElementById('final-balance').textContent=money(s.final_balance); document.getElementById('initial-label').textContent='Capital inicial '+money(s.initial_balance)+' · risco '+pct(s.risk_per_trade_pct); const pnl=document.getElementById('net-pnl'); pnl.textContent=money(s.net_pnl); pnl.className=s.net_pnl>=0?'green':'red'; document.getElementById('return-pct').textContent='Retorno '+pct(s.return_pct); document.getElementById('drawdown').textContent=money(s.max_drawdown); document.getElementById('drawdown-pct').textContent=pct(s.max_drawdown_pct)+' sobre o pico'; document.getElementById('trades').textContent=s.trades_simulated; document.getElementById('period').textContent=new Date(data.period_start_utc).toLocaleDateString('pt-BR')+' a '+new Date(data.period_end_utc).toLocaleDateString('pt-BR'); document.getElementById('status').textContent='Curva atualizada'; renderChart(data); }
    async function simulate(event) { if(event)event.preventDefault(); const form=document.getElementById('simulation-form'),params=new URLSearchParams(new FormData(form)); document.getElementById('status').textContent='Simulando...'; const response=await fetch('/api/growth-simulation?'+params); if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.detail||'Não foi possível executar a simulação.');} render(await response.json()); }
    document.getElementById('simulation-form').onsubmit=event=>simulate(event).catch(error=>document.getElementById('status').textContent=error.message); simulate().catch(error=>document.getElementById('status').textContent=error.message);
    </script>""")


def render_growth_simulator_page() -> HTMLResponse:
    return _page("2Lotus | Simulador", """<main><header class="header"><div><a class="brand brand-compact" href="/bots"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><p class="eyebrow">Happy Gold + Portfólio 7/6 · 100/100</p><h1>Simulador de crescimento</h1><p class="muted">Reaplique as operações anuais com risco composto e reduções permanentes por saldo.</p></div><div class="actions"><a href="/operations">Saúde</a><a href="/bots">Estratégias</a></div></header>
    <section class="panel controls"><form id="simulation-form"><label>Capital inicial (USD)<input id="initial-balance" type="number" min="1" max="100000000" step="1" value="10000" required></label><label>Risco por operação (%)<input id="base-risk" type="number" min="0.01" max="10" step="0.01" value="0.25" required></label><button class="primary" type="submit">Simular curva</button><div class="optional-tiers"><div class="tier-heading"><div><strong>Faixas de redução de risco</strong><small class="muted">Opcional</small></div><button id="add-tier" type="button">+ Adicionar faixa</button></div><div id="tiers"></div></div></form><p class="muted">Se adicionar faixas, o risco menor fica travado ao atingir o capital definido, mesmo que o saldo recue.</p></section>
    <section class="cards"><article class="card"><p class="muted">Saldo final</p><strong id="final-balance">-</strong><span id="minimum-balance">-</span></article><article class="card"><p class="muted">PnL / retorno</p><strong id="net-pnl">-</strong><span id="return-pct">-</span></article><article class="card"><p class="muted">Drawdown máximo</p><strong id="drawdown">-</strong><span id="drawdown-pct">-</span></article><article class="card"><p class="muted">Operações</p><strong id="trades">-</strong><span id="period">-</span></article></section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Curva de saldo</h2><p class="muted">Cenário calculado com o capital e o risco informados.</p></div><p class="muted" id="status">Carregando...</p></div><svg id="growth-chart" viewBox="0 0 1100 440" role="img"></svg><div id="milestones" class="milestones"></div></section>
    <section class="panel warning"><strong>Projeção histórica</strong><p class="muted">Não prevê resultados futuros e não modela lote mínimo, margem ou mudança de execução em volumes maiores.</p></section></main><style>
    .eyebrow{color:var(--green);font-size:12px;font-weight:800;text-transform:uppercase}.actions{display:flex;gap:14px}.actions a{color:var(--text)}.controls,.chart-panel,.warning{padding:20px;margin-bottom:18px}.controls form{display:grid;grid-template-columns:220px 220px auto;gap:18px;align-items:end}label{display:grid;gap:7px;color:var(--muted);font-size:13px}input{padding:10px;color:#fff;background:#000;border:1px solid var(--border);border-radius:7px;font:inherit}.optional-tiers{grid-column:1/-1;padding-top:4px}.tier-heading,.tier-row{display:flex;gap:10px;align-items:center}.tier-heading{justify-content:space-between;margin-bottom:8px}.tier-heading strong,.tier-heading small{display:block}.tier-heading small{margin-top:3px}.tier-row{margin-top:7px}.tier-row input{width:150px}.tier-row button,.tier-heading button{color:var(--muted);background:#000;border:1px solid var(--border);border-radius:6px;padding:8px}.primary{padding:11px 18px;background:#fff;color:#000;border:0;border-radius:7px;font-weight:800}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.card{padding:18px}.card strong{display:block;font-size:25px;margin-bottom:7px}.card span{color:var(--muted);font-size:13px}.chart-heading{display:flex;justify-content:space-between;gap:16px}#growth-chart{width:100%;min-height:330px}.milestones{display:flex;flex-wrap:wrap;gap:8px;border-top:1px solid #333;padding-top:12px}.milestones span{padding:7px 9px;background:#151515;border-radius:6px;color:var(--muted);font-size:12px}.milestones:empty{display:none}.warning{border-left:3px solid var(--yellow)}.warning p{margin:7px 0 0}.green{color:var(--green)}.red{color:var(--red)}@media(max-width:800px){.controls form,.cards{grid-template-columns:1fr 1fr}.primary{grid-column:1/-1}}@media(max-width:560px){.controls form,.cards{grid-template-columns:1fr}.primary{grid-column:auto}.tier-row{flex-wrap:wrap}.chart-heading,.actions{flex-direction:column}}
    </style><script>
    const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(v||0),pct=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';
    function addTier(threshold='',risk=''){const row=document.createElement('div');row.className='tier-row';row.innerHTML=`<input data-field="threshold" type="number" min="0" step="1" value="${threshold}" placeholder="Capital da faixa" aria-label="Saldo da faixa" required><span>USD →</span><input data-field="risk" type="number" min="0.01" max="10" step="0.01" value="${risk}" placeholder="Novo risco" aria-label="Risco da faixa" required><span>%</span><button type="button">Remover</button>`;row.querySelector('button').onclick=()=>row.remove();document.getElementById('tiers').append(row)} document.getElementById('add-tier').onclick=()=>addTier();
    function chart(data){const svg=document.getElementById('growth-chart'),series=data.simulation,W=1100,H=440,L=86,R=20,T=20,B=45,times=series.points.map(p=>+new Date(p.day+'T00:00:00Z')),vals=series.points.map(p=>+p.balance),minX=Math.min(...times),maxX=Math.max(...times),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.1,1),minY=Math.max(0,lo-pad),maxY=hi+pad,x=v=>L+(v-minX)*(W-L-R)/Math.max(maxX-minX,1),y=v=>T+(maxY-v)*(H-T-B)/Math.max(maxY-minY,1);const grid=[0,.25,.5,.75,1].map(r=>{const v=maxY-(maxY-minY)*r,yy=y(v);return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#292929"/><text x="${L-8}" y="${yy+4}" text-anchor="end" fill="#999" font-size="11">${money(v)}</text>`}).join(''),path=`<path d="${series.points.map((p,i)=>`${i?'L':'M'} ${x(+new Date(p.day+'T00:00:00Z'))} ${y(+p.balance)}`).join(' ')}" fill="none" stroke="#41d392" stroke-width="4"/>`;svg.innerHTML=grid+path}
    function render(data){const s=data.simulation;document.getElementById('final-balance').textContent=money(s.final_balance);document.getElementById('minimum-balance').textContent='Mínimo '+money(s.minimum_balance);const pnl=document.getElementById('net-pnl');pnl.textContent=money(s.net_pnl);pnl.className=s.net_pnl>=0?'green':'red';document.getElementById('return-pct').textContent=pct(s.return_pct);document.getElementById('drawdown').textContent=money(s.max_drawdown);document.getElementById('drawdown-pct').textContent=pct(s.max_drawdown_pct);document.getElementById('trades').textContent=s.trades_simulated;document.getElementById('period').textContent=new Date(data.period_start_utc).toLocaleDateString('pt-BR')+' a '+new Date(data.period_end_utc).toLocaleDateString('pt-BR');document.getElementById('milestones').innerHTML=s.milestones.map(m=>`<span>${money(m.balance_threshold)} · ${pct(m.risk_per_trade_pct)} · ${m.reached_at_utc?new Date(m.reached_at_utc).toLocaleDateString('pt-BR'):'não atingido'}</span>`).join('');document.getElementById('status').textContent='Curva atualizada';chart(data)}
    async function simulate(event){if(event)event.preventDefault();const tiers=[{balance_threshold:0,risk_per_trade_pct:+document.getElementById('base-risk').value},...[...document.querySelectorAll('.tier-row')].map(row=>({balance_threshold:+row.querySelector('[data-field="threshold"]').value,risk_per_trade_pct:+row.querySelector('[data-field="risk"]').value}))];document.getElementById('status').textContent='Simulando...';const response=await fetch('/api/growth-simulation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initial_balance:+document.getElementById('initial-balance').value,risk_tiers:tiers})});if(!response.ok){const p=await response.json().catch(()=>({}));throw new Error(p.detail||'Falha na simulação.')}render(await response.json())}document.getElementById('simulation-form').onsubmit=e=>simulate(e).catch(err=>document.getElementById('status').textContent=err.message);simulate().catch(err=>document.getElementById('status').textContent=err.message);
    </script>""")


def render_operations_page() -> HTMLResponse:
    return _page("2Lotus | Saúde operacional", """<main><header class="header"><div><a class="brand brand-compact" href="/bots"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><h1>Saúde operacional</h1><p class="muted">Heartbeat, mercado e snapshots das estratégias shadow.</p></div><div class="actions"><a href="/bots">Estratégias</a></div></header><section class="panel table"><table><thead><tr><th>Estratégia</th><th>Status</th><th>Último sucesso</th><th>Candle</th><th>Resposta / erro</th><th>Latência</th><th>Snapshot</th></tr></thead><tbody id="rows"><tr><td colspan="7" class="muted">Carregando...</td></tr></tbody></table></section><p id="updated" class="muted"></p></main><style>.actions a{color:var(--text)}.table{padding:0;overflow:auto}table{width:100%;min-width:950px;border-collapse:collapse}th,td{padding:15px;text-align:left;border-bottom:1px solid #292929}th{color:var(--muted);font-size:12px;text-transform:uppercase}.badge{padding:5px 8px;border-radius:999px;background:#222;font-size:11px}.healthy{color:var(--green)}.delayed,.market_closed{color:var(--yellow)}.stale{color:var(--red)}</style><script>const date=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'UTC'})+' UTC':'-';fetch('/api/operations').then(r=>{if(!r.ok)throw Error('Falha ao carregar saúde.');return r.json()}).then(data=>{document.getElementById('rows').innerHTML=data.bots.map(b=>`<tr><td><strong>${escapeHtml(b.name)}</strong><br><small class="muted">${escapeHtml(b.bot_id)}</small></td><td><span class="badge ${escapeHtml(b.status)}">${escapeHtml(b.status.replaceAll('_',' '))}</span><br><small class="muted">${b.consecutive_errors||0} erros</small></td><td>${date(b.last_success_at_utc||b.last_request_at_utc)}<br><small class="muted">tentativa ${date(b.last_attempt_at_utc)}</small></td><td>${date(b.last_candle_at_utc)}<br><small class="muted">atraso ${b.market_lag_seconds==null?'-':Math.round(b.market_lag_seconds/60)+' min'}</small></td><td>${escapeHtml(b.last_error_code||b.last_action||'-')}<br><small class="muted">${escapeHtml(b.last_error||b.last_reason||'')}</small></td><td>${b.last_latency_ms==null?'-':Number(b.last_latency_ms).toFixed(0)+' ms'}</td><td>${date(b.snapshot_updated_at_utc)}<br><small class="muted">dados até ${date(b.market_data_through_utc)}</small></td></tr>`).join('');document.getElementById('updated').textContent='Atualizado em '+date(data.updated_at_utc)}).catch(e=>document.getElementById('rows').textContent=e.message)</script>""")


def render_comparison_page(bots: list[BotCatalogItem]) -> HTMLResponse:
    rows = "".join(
        f'''<tr data-bot-id="{escape(bot.id)}"><td><a href="/bots/{escape(bot.id)}">{escape(bot.name)}</a><small>{escape(bot.strategy_profile)}</small></td><td>{escape(bot.symbol)} · {escape(bot.timeframe)}</td><td data-field="trades">-</td><td data-field="open">-</td><td data-field="win-rate">-</td><td data-field="profit-factor">-</td><td data-field="net-pnl">-</td><td data-field="latest">-</td></tr>'''
        for bot in bots
    ) or '<tr><td colspan="8" class="muted">Nenhum bot foi cadastrado.</td></tr>'
    return _page("2Lotus | Comparação", f"""<main><header class="header"><div><a class="brand brand-compact" href="/bots" aria-label="2Lotus"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><h1>Comparação das estratégias</h1><p class="muted">Todos os resultados abaixo são paper trades enquanto o modo shadow estiver ativo.</p></div><div class="actions"><a href="/bots">Estratégias</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form><p class="muted" id="updated-at">Carregando...</p></div></header>
    <section class="summary-grid"><article class="panel"><p class="muted">Estratégias ativas</p><strong>{len(bots)}</strong></article><article class="panel"><p class="muted">Mercado acompanhado</p><strong>XAUUSD · M5</strong></article><article class="panel"><p class="muted">Execução</p><strong class="yellow">Shadow</strong></article></section>
    <section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Estratégia</th><th>Mercado</th><th>Fechados</th><th>Abertos</th><th>Win rate</th><th>Profit factor</th><th>PnL líquido</th><th>Último evento</th></tr></thead><tbody>{rows}</tbody></table></div></section>
    <p class="muted note">As posições são isoladas por bot e variante. Um sinal de uma estratégia não bloqueia nem encerra posições das demais.</p></main><style>
    .actions {{ display:flex; justify-content:flex-end; align-items:flex-start; gap:14px; flex-wrap:wrap; }} .actions a {{ color:var(--text); }} .actions p {{ width:100%; text-align:right; }} .summary-grid {{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; margin-bottom:18px; }} .summary-grid .panel {{ padding:18px; }} .summary-grid strong {{ display:block; font-size:24px; }} .table-panel {{ padding:0; overflow:hidden; }} .table-wrap {{ overflow-x:auto; }} table {{ width:100%; border-collapse:collapse; min-width:980px; }} th,td {{ padding:16px; text-align:left; border-bottom:1px solid rgba(255,255,255,.16); }} th {{ color:var(--muted); font-size:12px; text-transform:uppercase; letter-spacing:.05em; }} td a {{ color:var(--text); font-weight:700; }} td small {{ display:block; margin-top:5px; color:var(--muted); }} .green {{ color:var(--green); }} .red {{ color:var(--red); }} .yellow {{ color:var(--yellow); }} .note {{ margin:18px 2px 0; }} @media(max-width:720px) {{ .summary-grid {{ grid-template-columns:1fr; }} }}
    </style><script>
    const money = value => new Intl.NumberFormat('pt-BR', {{style:'currency',currency:'USD'}}).format(value || 0);
    const date = value => value ? new Date(value).toLocaleString('pt-BR', {{timeZone:'UTC'}}) + ' UTC' : 'Sem eventos';
    const color = value => value > 0 ? 'green' : value < 0 ? 'red' : 'yellow';
    async function loadComparison() {{
      const response = await fetch('/api/compare');
      if (!response.ok) throw new Error('Não foi possível carregar a comparação.');
      const data = await response.json();
      for (const bot of data.bots) {{
        const row = document.querySelector(`[data-bot-id="${{bot.id}}"]`);
        if (!row) continue;
        const summary = bot.summary;
        row.querySelector('[data-field="trades"]').textContent = summary.trades_count;
        row.querySelector('[data-field="open"]').textContent = summary.open_positions;
        row.querySelector('[data-field="win-rate"]').textContent = summary.win_rate_pct.toFixed(2) + '%';
        row.querySelector('[data-field="profit-factor"]').textContent = summary.profit_factor.toFixed(2);
        const pnl = row.querySelector('[data-field="net-pnl"]'); pnl.textContent = money(summary.net_pnl); pnl.className = color(summary.net_pnl);
        row.querySelector('[data-field="latest"]').textContent = date(bot.latest_trade_at_utc);
      }}
      document.getElementById('updated-at').textContent = 'Atualizado em ' + date(data.updated_at_utc);
    }}
    loadComparison().catch(error => document.getElementById('updated-at').textContent = error.message);
    </script>""")


def render_strategy_description(description: str) -> str:
    lines = [line.strip() for line in description.splitlines() if line.strip()]
    bullet_items = [line.removeprefix("- ").strip() for line in lines if line.startswith("- ")]
    if bullet_items and len(bullet_items) == len(lines):
        return '<ul class="strategy-list">' + "".join(f"<li>{escape(item)}</li>" for item in bullet_items) + "</ul>"
    return f'<p class="strategy-text">{escape(description)}</p>'


def _render_results_page_legacy(bot: BotCatalogItem) -> HTMLResponse:
    bot_id = escape(bot.id)
    strategy_description = render_strategy_description(bot.strategy_description or bot.description)
    return _page(f"{bot.name} | Resultados", f"""<main><header class="header"><div><a class="brand brand-compact" href="/bots" aria-label="Voltar para todos os bots"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)} · {escape(bot.strategy_profile)}</p><h1>{escape(bot.name)}</h1><p class="muted">{escape(bot.description)}</p></div><div class="actions"><a href="/compare">Comparar</a><a href="/bots">Todos os bots</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form><p class="muted" id="latest-trade">Carregando...</p></div></header>
    <section class="cards"><article class="card"><p class="muted">PnL líquido</p><strong id="net-pnl">-</strong><span id="gross-pnl"></span></article><article class="card"><p class="muted">Trades fechados</p><strong id="trades-count">-</strong><span id="open-positions"></span></article><article class="card"><p class="muted">Win rate</p><strong id="win-rate">-</strong><span id="wl-breakdown"></span></article><article class="card"><p class="muted">Profit factor</p><strong id="profit-factor">-</strong><span id="avg-rr"></span></article><article class="card"><p class="muted">Melhor / pior</p><strong id="best-trade">-</strong><span id="worst-trade"></span></article></section>
    <section class="panel strategy-card"><p class="muted">Estratégia utilizada</p><h2>{escape(bot.strategy_profile)}</h2>{strategy_description}</section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Preço e operações</h2><p class="muted">Arraste para voltar ou avançar no tempo; use o scroll para alterar a quantidade de candles visíveis.</p></div><div class="legend"><label>Tempo <select id="chart-timeframe"><option value="M5">M5</option><option value="M15">M15</option><option value="H1">H1</option></select></label><span><i class="entry-buy"></i>Compra</span><span><i class="entry-sell"></i>Venda</span><span><i class="exit"></i>Fechamento</span><button id="chart-reset" type="button">Mais recente</button></div></div><div id="market-chart-empty" class="muted">Carregando gráfico...</div><svg id="market-chart" viewBox="0 0 1000 360" role="img" aria-label="Gráfico de preço com operações do bot" tabindex="0" hidden></svg><input id="chart-timeline" type="range" min="0" value="0" aria-label="Navegar no histórico do gráfico"></section>
    <section class="layout"><article class="panel"><h2>PnL diário</h2><div id="daily-pnl"></div></article><article class="panel"><h2>Trades recentes</h2><div id="recent-trades"></div></article></section></main><style>
    .actions {{ display:flex; align-items:flex-start; justify-content:flex-end; flex-wrap:wrap; gap:12px; text-align:right; }} .actions a {{ color:var(--text); }} .actions p {{ width:100%; margin:0; }} .cards {{ display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; margin-bottom:20px; }} .card,.panel {{ padding:18px; }} .card strong {{ display:block; font-size:27px; margin-bottom:9px; }} .card span {{ color:var(--muted); font-size:13px; }} .strategy-card {{ margin-bottom:16px; border-left:3px solid #fff; }} .strategy-card h2 {{ font-size:18px; margin-bottom:8px; }} .strategy-text,.strategy-list {{ margin:0; line-height:1.55; color:var(--muted); max-width:900px; }} .strategy-list {{ display:grid; gap:8px; padding-left:20px; }} .strategy-list li::marker {{ color:#fff; }} .chart-panel {{ margin-bottom:16px; }} .chart-heading {{ display:flex; align-items:flex-start; justify-content:space-between; gap:16px; }} .chart-heading h2 {{ margin-bottom:6px; }} .legend {{ display:flex; gap:12px; flex-wrap:wrap; font-size:13px; color:var(--muted); }} .legend span {{ display:inline-flex; align-items:center; gap:6px; }} .legend i {{ display:inline-block; width:10px; height:10px; }} .legend button {{ border:1px solid var(--border); border-radius:6px; padding:4px 8px; background:#000; color:var(--text); }} .entry-buy {{ background:var(--green); clip-path:polygon(50% 0,100% 100%,0 100%); }} .entry-sell {{ background:var(--red); clip-path:polygon(0 0,100% 0,50% 100%); }} .exit {{ border:2px solid var(--yellow); border-radius:50%; }} #market-chart {{ width:100%; min-height:300px; background:#000; border:1px solid var(--border); border-radius:8px; cursor:grab; touch-action:none; }} #market-chart:active {{ cursor:grabbing; }} .layout {{ display:grid; grid-template-columns:1.2fr .8fr; gap:16px; }} .daily-row,.trade-row {{ display:grid; gap:12px; padding:12px 0; border-top:1px solid rgba(255,255,255,.16); }} .daily-row {{ grid-template-columns:1fr auto; }} .trade-row {{ grid-template-columns:70px 70px 1fr auto; }} .bar {{ height:8px; border-radius:999px; background:#000; overflow:hidden; }} .bar span {{ display:block; height:100%; background:#fff; }} .green {{ color:var(--green); }} .red {{ color:var(--red); }} .yellow {{ color:var(--yellow); }} @media(max-width:1080px) {{ .cards {{ grid-template-columns:repeat(2,minmax(0,1fr)); }} .layout {{ grid-template-columns:1fr; }} }} @media(max-width:640px) {{ .cards {{ grid-template-columns:1fr; }} .chart-heading {{ flex-direction:column; }} .trade-row {{ grid-template-columns:1fr; gap:5px; }} }}
    </style><script>
    const money = value => new Intl.NumberFormat('pt-BR', {{style:'currency',currency:'USD'}}).format(value || 0); const date = value => value ? new Date(value).toLocaleString('pt-BR', {{timeZone:'UTC'}}) + ' UTC' : '-'; const color = value => value > 0 ? 'green' : value < 0 ? 'red' : 'yellow';
    async function load() {{ const response = await fetch('/api/bots/{bot_id}/results'); if (!response.ok) throw new Error('Não foi possível carregar os resultados.'); const data = await response.json(); const s = data.summary; document.getElementById('latest-trade').textContent = data.latest_trade_at_utc ? 'Último trade registrado em ' + date(data.latest_trade_at_utc) : 'Sem operações registradas'; document.getElementById('net-pnl').textContent = money(s.net_pnl); document.getElementById('net-pnl').className = color(s.net_pnl); document.getElementById('gross-pnl').textContent = 'Lucro ' + money(s.gross_profit) + ' | Perda ' + money(s.gross_loss); document.getElementById('trades-count').textContent = s.trades_count; document.getElementById('open-positions').textContent = s.open_positions + ' posições em aberto'; document.getElementById('win-rate').textContent = s.win_rate_pct.toFixed(2) + '%'; document.getElementById('wl-breakdown').textContent = s.wins + ' wins | ' + s.losses + ' losses'; document.getElementById('profit-factor').textContent = s.profit_factor.toFixed(2); document.getElementById('avg-rr').textContent = 'RR médio ' + s.avg_rr.toFixed(2); document.getElementById('best-trade').textContent = money(s.best_trade); document.getElementById('best-trade').className = color(s.best_trade); document.getElementById('worst-trade').textContent = 'Pior ' + money(s.worst_trade); const daily = document.getElementById('daily-pnl'); daily.innerHTML = data.daily_pnl.length ? data.daily_pnl.slice(-12).reverse().map(p => `<div class="daily-row"><span>${{new Date(p.day + 'T00:00:00Z').toLocaleDateString('pt-BR')}}</span><span class="${{color(p.net_pnl)}}">${{money(p.net_pnl)}}</span><div class="bar"><span style="width:${{Math.max(Math.abs(p.net_pnl), 4)}}%"></span></div></div>`).join('') : '<p class="muted">Ainda não há trades fechados.</p>'; const trades = document.getElementById('recent-trades'); trades.innerHTML = data.recent_trades.length ? data.recent_trades.map(t => `<div class="trade-row"><strong>${{escapeHtml(t.side.toUpperCase())}}</strong><span class="muted">${{escapeHtml(t.symbol)}}<br>${{escapeHtml(t.timeframe)}}</span><span>${{escapeHtml(t.setup)}}<br><small class="muted">${{date(t.closed_at_utc || t.opened_at_utc)}}</small></span><strong class="${{color(t.net_pnl)}}">${{money(t.net_pnl)}}</strong></div>`).join('') : '<p class="muted">Sem histórico recente.</p>'; }} load().catch(error => document.getElementById('latest-trade').textContent = error.message);
    function enableChartNavigation(svg) {{ let view = {{x:0,y:0,w:1000,h:360}}, drag = null; const apply = () => svg.setAttribute('viewBox', `${{view.x}} ${{view.y}} ${{view.w}} ${{view.h}}`); const reset = () => {{ view = {{x:0,y:0,w:1000,h:360}}; apply(); }}; document.getElementById('chart-reset').onclick = reset; svg.ondblclick = reset; svg.onwheel = event => {{ event.preventDefault(); const factor = event.deltaY < 0 ? .85 : 1.18; const nextW = Math.max(260, Math.min(1000, view.w * factor)); const nextH = Math.max(94, Math.min(360, view.h * factor)); const rect = svg.getBoundingClientRect(), px = (event.clientX-rect.left)/rect.width, py = (event.clientY-rect.top)/rect.height; view.x += (view.w-nextW)*px; view.y += (view.h-nextH)*py; view.w = nextW; view.h = nextH; apply(); }}; svg.onpointerdown = event => {{ drag = {{x:event.clientX,y:event.clientY,view:{{...view}}}}; svg.setPointerCapture(event.pointerId); }}; svg.onpointermove = event => {{ if (!drag) return; const rect = svg.getBoundingClientRect(); view.x = drag.view.x - (event.clientX-drag.x)*drag.view.w/rect.width; view.y = drag.view.y - (event.clientY-drag.y)*drag.view.h/rect.height; apply(); }}; svg.onpointerup = () => drag = null; }}
    async function loadChart() {{ const empty = document.getElementById('market-chart-empty'); const svg = document.getElementById('market-chart'); const response = await fetch('/api/bots/{bot_id}/chart'); if (!response.ok) throw new Error('Não foi possível carregar o gráfico.'); const data = await response.json(); const candles = data.candles || []; if (!candles.length) {{ empty.textContent = 'Os candles aparecerão após os primeiros ciclos do MT5.'; return; }} const width = 1000, height = 360, pad = {{left:62,right:18,top:18,bottom:34}}; const prices = candles.flatMap(c => [Number(c.high), Number(c.low)]); const high = Math.max(...prices), low = Math.min(...prices), range = Math.max(high - low, 0.00001); const x = index => pad.left + (candles.length === 1 ? 0 : index * (width - pad.left - pad.right) / (candles.length - 1)); const y = price => pad.top + (high - price) * (height - pad.top - pad.bottom) / range; const step = Math.max(3, (width - pad.left - pad.right) / Math.max(candles.length, 1)); const bodyWidth = Math.max(2, Math.min(10, step * .58)); const lines = [0,.25,.5,.75,1].map(r => {{ const value = high - range * r; const yy = y(value); return `<g><line x1="${{pad.left}}" x2="${{width-pad.right}}" y1="${{yy}}" y2="${{yy}}" stroke="#273654"/><text x="4" y="${{yy+4}}" fill="#9fb0d4" font-size="11">${{value.toFixed(2)}}</text></g>`; }}).join(''); const bodies = candles.map((c, index) => {{ const open = Number(c.open), close = Number(c.close), top = Math.min(y(open), y(close)), body = Math.max(1.5, Math.abs(y(open)-y(close))), up = close >= open, cx = x(index); return `<g><line x1="${{cx}}" x2="${{cx}}" y1="${{y(Number(c.high))}}" y2="${{y(Number(c.low))}}" stroke="${{up ? '#41d392' : '#ff6b81'}}"/><rect x="${{cx-bodyWidth/2}}" y="${{top}}" width="${{bodyWidth}}" height="${{body}}" fill="${{up ? '#41d392' : '#ff6b81'}}"/></g>`; }}).join(''); const nearest = timestamp => {{ const target = new Date(timestamp).getTime(); return candles.reduce((best, candle, index) => Math.abs(new Date(candle.timestamp_utc).getTime()-target) < Math.abs(new Date(candles[best].timestamp_utc).getTime()-target) ? index : best, 0); }}; const first = new Date(candles[0].timestamp_utc).getTime(), last = new Date(candles[candles.length-1].timestamp_utc).getTime(); const markers = (data.trades || []).flatMap(t => {{ const entryTime = new Date(t.opened_at_utc).getTime(), closeTime = t.closed_at_utc ? new Date(t.closed_at_utc).getTime() : null, marker = []; if (entryTime >= first && entryTime <= last) {{ const cx = x(nearest(t.opened_at_utc)), cy = y(Number(t.entry_price)), buy = t.side === 'buy'; marker.push(`<polygon points="${{cx}},${{cy + (buy ? -11 : 11)}} ${{cx-7}},${{cy + (buy ? 3 : -3)}} ${{cx+7}},${{cy + (buy ? 3 : -3)}}" fill="${{buy ? '#41d392' : '#ff6b81'}}"><title>${{buy ? 'Compra' : 'Venda'}} ${{Number(t.entry_price).toFixed(2)}}</title></polygon>`); }} if (closeTime && closeTime >= first && closeTime <= last && t.exit_price !== null) {{ const cx = x(nearest(t.closed_at_utc)), cy = y(Number(t.exit_price)); marker.push(`<circle cx="${{cx}}" cy="${{cy}}" r="5" fill="#0d1527" stroke="#f6c667" stroke-width="2"><title>Fechamento ${{Number(t.exit_price).toFixed(2)}}</title></circle>`); }} return marker; }}).join(''); const labels = `<text x="${{pad.left}}" y="${{height-10}}" fill="#9fb0d4" font-size="11">${{new Date(candles[0].timestamp_utc).toLocaleString('pt-BR', {{timeZone:'UTC'}})}} UTC</text><text x="${{width-pad.right}}" y="${{height-10}}" text-anchor="end" fill="#9fb0d4" font-size="11">${{new Date(candles[candles.length-1].timestamp_utc).toLocaleString('pt-BR', {{timeZone:'UTC'}})}} UTC</text>`; svg.innerHTML = lines + bodies + markers + labels; empty.hidden = true; svg.hidden = false; enableChartNavigation(svg); }} load().then(loadChart).catch(error => {{ document.getElementById('latest-trade').textContent = error.message; const empty = document.getElementById('market-chart-empty'); if (empty) empty.textContent = error.message; }});
    async function loadTradingChart() {{ return Promise.resolve(); }}
    async function loadAnnotatedTradingChart() {{
      const svg = document.getElementById('market-chart'), empty = document.getElementById('market-chart-empty'), select = document.getElementById('chart-timeframe'), timeline = document.getElementById('chart-timeline');
      const response = await fetch('/api/bots/{bot_id}/chart');
      if (!response.ok) throw new Error('Não foi possível carregar o gráfico.');
      const data = await response.json(), base = data.candles || [];
      if (!base.length) return;
      let visible = 90, end = base.length, drag = null;
      const grouped = () => {{
        const size = {{M5:1,M15:3,H1:12}}[select.value];
        const output = [];
        for (let index = 0; index < base.length; index += size) {{
          const group = base.slice(index, index + size);
          if (group.length === size) output.push({{timestamp_utc:group[0].timestamp_utc,open:+group[0].open,high:Math.max(...group.map(c=>+c.high)),low:Math.min(...group.map(c=>+c.low)),close:+group.at(-1).close}});
        }}
        return output;
      }};
      const render = () => {{
        const all = grouped();
        end = Math.min(end, all.length);
        visible = Math.min(visible, all.length);
        const start = Math.max(0, end - visible), part = all.slice(start, end), W = 1000, H = 360, L = 58, R = 16, T = 16, B = 30;
        const prices = part.flatMap(c => [c.high, c.low]), hi = Math.max(...prices), lo = Math.min(...prices), range = Math.max(hi - lo, .001);
        const x = index => L + index * (W - L - R) / Math.max(part.length - 1, 1), y = value => T + (hi - value) * (H - T - B) / range, step = (W - L - R) / part.length;
        const grid = [0,.25,.5,.75,1].map(r => `<line x1="${{L}}" x2="${{W-R}}" y1="${{y(hi-range*r)}}" y2="${{y(hi-range*r)}}" stroke="#273654"/>`).join('');
        const bars = part.map((c, index) => {{ const up = c.close >= c.open, xx = x(index), top = Math.min(y(c.open), y(c.close)); return `<line x1="${{xx}}" x2="${{xx}}" y1="${{y(c.high)}}" y2="${{y(c.low)}}" stroke="${{up?'#41d392':'#ff6b81'}}"/><rect x="${{xx-step*.28}}" y="${{top}}" width="${{Math.max(2,step*.56)}}" height="${{Math.max(1,Math.abs(y(c.open)-y(c.close)))}}" fill="${{up?'#41d392':'#ff6b81'}}"/>`; }}).join('');
        const nearestIndex = time => all.reduce((best, candle, index) => Math.abs(+new Date(candle.timestamp_utc)-time) < Math.abs(+new Date(all[best].timestamp_utc)-time) ? index : best, 0);
        const marks = (data.trades || []).flatMap(trade => {{
          const eventIndex = nearestIndex(+new Date(trade.opened_at_utc));
          if (eventIndex < start || eventIndex >= end) return [];
          const candle = part[eventIndex - start], xx = x(eventIndex - start), testEvent = trade.setup.endsWith('_paper_trade');
          const price = +trade.entry_price, hasMatchingPrice = price >= lo && price <= hi;
          const yy = hasMatchingPrice ? y(price) : Math.max(T + 10, y(candle.high) - 12);
          const buy = trade.side === 'buy', fill = testEvent ? '#4f8cff' : (buy ? '#41d392' : '#ff6b81');
          const title = testEvent ? `Evento de teste — ${{new Date(trade.opened_at_utc).toLocaleString('pt-BR',{{timeZone:'UTC'}})}} UTC` : (buy ? 'Compra' : 'Venda');
          return [`<polygon points="${{xx}},${{yy-8}} ${{xx+8}},${{yy}} ${{xx}},${{yy+8}} ${{xx-8}},${{yy}}" fill="${{fill}}"><title>${{title}}</title></polygon>`];
        }}).join('');
        svg.innerHTML = grid + bars + marks;
        svg.hidden = false; empty.hidden = true;
        timeline.max = Math.max(0, all.length - visible); timeline.value = all.length - end;
      }};
      const move = delta => {{ const all = grouped(); end = Math.max(visible, Math.min(all.length, end + delta)); render(); }};
      select.onchange = () => {{ end = grouped().length; render(); }};
      timeline.oninput = () => {{ end = grouped().length - (+timeline.value); render(); }};
      document.getElementById('chart-reset').onclick = () => {{ end = grouped().length; visible = 90; render(); }};
      svg.onwheel = event => {{ event.preventDefault(); visible = Math.max(12, Math.min(180, visible + (event.deltaY > 0 ? 8 : -8))); render(); }};
      svg.onpointerdown = event => {{ drag = event.clientX; svg.setPointerCapture(event.pointerId); }};
      svg.onpointermove = event => {{ if (drag === null) return; const delta = Math.round((drag - event.clientX) / Math.max(8, svg.clientWidth / visible)); if (delta) {{ move(delta); drag = event.clientX; }} }};
      svg.onpointerup = () => drag = null;
      render();
    }}
    let annotatedChartAttempts = 0;
    const annotatedChartTimer = setInterval(() => {{
      loadAnnotatedTradingChart().catch(error => {{ document.getElementById('market-chart-empty').textContent = error.message; }});
      if (++annotatedChartAttempts >= 8) clearInterval(annotatedChartTimer);
    }}, 500);
    function loadChart() {{ return Promise.resolve(); }}
    </script>""")


def render_results_page(bot: BotCatalogItem) -> HTMLResponse:
    bot_id = escape(bot.id)
    strategy_description = render_strategy_description(bot.strategy_description or bot.description)
    return _page(f"{bot.name} | Resultados", f"""<main><header class="header"><div><a class="brand brand-compact" href="/bots" aria-label="Voltar para estratégias"><img src="/static/brand/logo-1-white-no-bg.png" alt="2Lotus"></a><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)} · {escape(bot.strategy_profile)}</p><h1>{escape(bot.name)}</h1><p class="muted">{escape(bot.description)}</p></div><div class="actions"><a href="/compare">Comparar</a><a href="/bots">Estratégias</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section class="mode panel"><div><p class="eyebrow">Fonte dos resultados</p><select id="result-mode"><option value="replay" selected>Validação histórica</option><option value="live">Acompanhamento ao vivo / shadow</option></select></div><label>Período <select id="replay-days"><option value="30">30 dias</option><option value="120">120 dias</option><option value="365" selected>365 dias</option></select></label><p id="period-label" class="muted">Carregando validação histórica...</p></section>
    <section class="cards"><article class="card"><p class="muted">PnL líquido</p><strong id="net-pnl">-</strong><span id="gross-pnl"></span></article><article class="card"><p class="muted">Trades fechados</p><strong id="trades-count">-</strong><span id="open-positions"></span></article><article class="card"><p class="muted">Win rate</p><strong id="win-rate">-</strong><span id="wl-breakdown"></span></article><article class="card"><p class="muted">Profit factor</p><strong id="profit-factor">-</strong><span id="avg-rr"></span></article><article class="card"><p class="muted">Gatilhos elegíveis</p><strong id="eligible-count">-</strong><span id="candidate-count"></span></article></section>
    <section class="panel strategy-card"><p class="muted">Estratégia utilizada</p><h2>{escape(bot.strategy_profile)}</h2>{strategy_description}</section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Preço e eventos simulados</h2><p class="muted">Losangos marcam entradas; círculos marcam saídas. Arraste a linha do tempo ou use o scroll para alterar o zoom.</p></div><div class="legend"><label>Tempo <select id="chart-timeframe"><option value="M5">M5</option><option value="M15">M15</option><option value="H1">H1</option></select></label><span><i class="entry-buy"></i>Compra</span><span><i class="entry-sell"></i>Venda</span><span><i class="exit"></i>Saída</span><button id="chart-reset" type="button">Mais recente</button></div></div><div id="market-chart-empty" class="muted">Carregando gráfico...</div><svg id="market-chart" viewBox="0 0 1000 360" role="img" aria-label="Gráfico com operações simuladas" hidden></svg><input id="chart-timeline" type="range" min="0" value="0" aria-label="Navegar no histórico"></section>
    <section class="layout"><article class="panel"><h2>PnL diário</h2><div id="daily-pnl"></div></article><article class="panel"><h2>Operações do período</h2><div id="recent-trades"></div></article></section>
    <section id="validation-panel" class="panel validation"><div><p class="muted">Expectativa líquida</p><strong id="expectancy-r">-</strong></div><div><p class="muted">Drawdown máximo</p><strong id="max-drawdown">-</strong></div><div><p class="muted">Janelas positivas</p><strong id="positive-folds">-</strong></div><div><p class="muted">Status estatístico</p><strong id="validation-status">-</strong></div><div class="validation-wide"><p class="muted">Principais bloqueios do filtro</p><p id="blocked-reasons">-</p></div></section>
    <section id="assumptions-panel" class="panel assumptions"><h2>Premissas do replay</h2><ul id="assumptions"></ul></section></main><style>
    .actions {{ display:flex; gap:12px; align-items:flex-start; }} .actions a {{ color:var(--text); }} .mode {{ display:flex; justify-content:space-between; align-items:center; gap:18px; padding:16px 18px; margin-bottom:18px; border-color:#4f8cff; }} .eyebrow {{ margin:0 0 7px; color:#8eb4ff; font-size:12px; text-transform:uppercase; letter-spacing:.08em; }} select {{ color:var(--text); background:#000; border:1px solid var(--border); border-radius:7px; padding:8px; }} .cards {{ display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; margin-bottom:18px; }} .card,.panel {{ padding:18px; }} .card strong {{ display:block; font-size:27px; margin-bottom:8px; }} .card span {{ color:var(--muted); font-size:13px; }} .strategy-card,.chart-panel {{ margin-bottom:16px; }} .strategy-card {{ border-left:3px solid #fff; }} .strategy-list,.strategy-text {{ color:var(--muted); line-height:1.55; }} .chart-heading {{ display:flex; justify-content:space-between; gap:16px; }} .legend {{ display:flex; flex-wrap:wrap; gap:12px; align-items:center; color:var(--muted); font-size:13px; }} .legend span {{ display:inline-flex; gap:6px; align-items:center; }} .legend i {{ display:block; width:10px; height:10px; }} .entry-buy {{ background:var(--green); transform:rotate(45deg); }} .entry-sell {{ background:var(--red); transform:rotate(45deg); }} .exit {{ border:2px solid var(--yellow); border-radius:50%; }} .legend button {{ border:1px solid var(--border); border-radius:7px; padding:7px 9px; color:var(--text); background:#000; }} #market-chart {{ width:100%; min-height:300px; background:#000; border:1px solid var(--border); border-radius:8px; touch-action:none; }} #chart-timeline {{ width:100%; margin-top:12px; }} .layout {{ display:grid; grid-template-columns:1fr 1fr; gap:16px; }} .daily-row,.trade-row {{ display:grid; gap:10px; padding:11px 0; border-top:1px solid rgba(255,255,255,.16); }} .daily-row {{ grid-template-columns:1fr auto; }} .trade-row {{ grid-template-columns:64px 1fr auto; }} .validation {{ display:grid; grid-template-columns:repeat(4,1fr); gap:18px; margin-top:16px; }} .validation strong {{ font-size:22px; }} .validation-wide {{ grid-column:1/-1; }} .assumptions {{ margin-top:16px; }} .assumptions li {{ color:var(--muted); margin:8px 0; }} .green {{ color:var(--green); }} .red {{ color:var(--red); }} .yellow {{ color:var(--yellow); }} @media(max-width:1000px) {{ .cards {{ grid-template-columns:repeat(2,1fr); }} .layout,.validation {{ grid-template-columns:1fr; }} .validation-wide {{ grid-column:auto; }} }} @media(max-width:640px) {{ .cards {{ grid-template-columns:1fr; }} .mode,.chart-heading,.actions {{ flex-direction:column; align-items:flex-start; }} }}
    </style><script>
    const money = value => new Intl.NumberFormat('pt-BR', {{style:'currency',currency:'USD'}}).format(value || 0);
    const date = value => value ? new Date(value).toLocaleString('pt-BR', {{timeZone:'UTC'}}) + ' UTC' : '-';
    const color = value => value > 0 ? 'green' : value < 0 ? 'red' : 'yellow';
    const priceDigits = {5 if bot.symbol.upper() == "EURUSD" else 2};
    let chartData = null, visible = 120, end = 0;
    async function fetchData() {{
      if (document.getElementById('result-mode').value === 'replay') {{
        const days = document.getElementById('replay-days').value;
        const response = await fetch('/api/bots/{bot_id}/historical-replay?days=' + days);
        if (!response.ok) throw new Error('Não foi possível executar o replay histórico.');
        return response.json();
      }}
      const [resultsResponse, chartResponse] = await Promise.all([fetch('/api/bots/{bot_id}/results'), fetch('/api/bots/{bot_id}/chart')]);
      if (!resultsResponse.ok || !chartResponse.ok) throw new Error('Não foi possível carregar o acompanhamento.');
      const results = await resultsResponse.json(), chart = await chartResponse.json();
      return {{...results, ...chart, candidates_detected:null, candles_evaluated:chart.candles.length, assumptions:[]}};
    }}
    function renderSummary(data) {{
      const s = data.summary;
      document.getElementById('net-pnl').textContent = money(s.net_pnl); document.getElementById('net-pnl').className = color(s.net_pnl);
      document.getElementById('gross-pnl').textContent = 'Lucro ' + money(s.gross_profit) + ' | Perda ' + money(s.gross_loss);
      document.getElementById('trades-count').textContent = s.trades_count; document.getElementById('open-positions').textContent = s.open_positions + ' em aberto';
      document.getElementById('win-rate').textContent = s.win_rate_pct.toFixed(2) + '%'; document.getElementById('wl-breakdown').textContent = s.wins + ' wins | ' + s.losses + ' losses';
      document.getElementById('profit-factor').textContent = s.profit_factor.toFixed(2); document.getElementById('avg-rr').textContent = 'RR médio ' + s.avg_rr.toFixed(2);
      document.getElementById('eligible-count').textContent = data.candidates_eligible ?? '-'; document.getElementById('candidate-count').textContent = (data.candidates_detected ?? '-') + ' detectados · ' + (data.candidates_blocked ?? '-') + ' bloqueados';
      const folds=data.validation_folds||[], populated=folds.filter(f=>f.trades_count>0), positive=populated.filter(f=>f.positive).length; document.getElementById('expectancy-r').textContent=(data.expectancy_r??0).toFixed(3)+'R'; document.getElementById('expectancy-r').className=color(data.expectancy_r); document.getElementById('max-drawdown').textContent=(data.max_drawdown_r??0).toFixed(2)+'R'; document.getElementById('positive-folds').textContent=positive+'/'+populated.length; document.getElementById('validation-status').textContent=(data.validation_status||'-').replaceAll('_',' '); document.getElementById('validation-status').title=data.validation_reason||''; document.getElementById('blocked-reasons').textContent=Object.entries(data.blocked_reasons||{{}}).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([reason,count])=>reason+' ('+count+')').join(' · ')||'-'; document.getElementById('validation-panel').hidden=!data.period_start_utc;
      const replay = data.period_start_utc; document.getElementById('period-label').textContent = replay ? date(data.period_start_utc) + ' até ' + date(data.period_end_utc) : 'Dados recebidos do MT5';
      document.getElementById('daily-pnl').innerHTML = data.daily_pnl.length ? data.daily_pnl.slice().reverse().map(p => `<div class="daily-row"><span>${{new Date(p.day+'T00:00:00Z').toLocaleDateString('pt-BR')}}</span><strong class="${{color(p.net_pnl)}}">${{money(p.net_pnl)}}</strong></div>`).join('') : '<p class="muted">Nenhuma operação fechada no período.</p>';
      const trades = data.trades || data.recent_trades || []; document.getElementById('recent-trades').innerHTML = trades.length ? trades.slice().reverse().map(t => `<div class="trade-row"><strong>${{escapeHtml(t.side.toUpperCase())}}</strong><span>${{escapeHtml(t.setup.replace('_historical_replay',''))}}<br><small class="muted">${{date(t.opened_at_utc)}} → ${{date(t.closed_at_utc)}}</small></span><strong class="${{color(t.net_pnl)}}">${{t.closed_at_utc ? money(t.net_pnl) : 'ABERTA'}}</strong></div>`).join('') : '<p class="muted">Nenhum gatilho abriu operação.</p>';
      const assumptions = data.assumptions || []; document.getElementById('assumptions-panel').hidden = !assumptions.length; document.getElementById('assumptions').innerHTML = assumptions.map(item => `<li>${{escapeHtml(item)}}</li>`).join('');
    }}
    function groupedCandles() {{
      const base = chartData.candles || [], size = {{M5:1,M15:3,H1:12}}[document.getElementById('chart-timeframe').value]; const output=[];
      for (let i=0;i<base.length;i+=size) {{ const group=base.slice(i,i+size); if(group.length===size) output.push({{timestamp_utc:group[0].timestamp_utc,open:+group[0].open,high:Math.max(...group.map(c=>+c.high)),low:Math.min(...group.map(c=>+c.low)),close:+group.at(-1).close}}); }} return output;
    }}
    function renderChart() {{
      const all=groupedCandles(), svg=document.getElementById('market-chart'), empty=document.getElementById('market-chart-empty'); if(!all.length) {{ empty.textContent='Não há candles para este período.'; return; }}
      end=Math.min(end||all.length,all.length); visible=Math.min(visible,all.length); const start=Math.max(0,end-visible), part=all.slice(start,end), W=1000,H=360,L=58,R=16,T=16,B=30;
      const prices=part.flatMap(c=>[c.high,c.low]), hi=Math.max(...prices),lo=Math.min(...prices),range=Math.max(hi-lo,priceDigits===5?.00001:.001), x=i=>L+i*(W-L-R)/Math.max(part.length-1,1), y=v=>T+(hi-v)*(H-T-B)/range, step=(W-L-R)/Math.max(part.length,1);
      const grid=[0,.25,.5,.75,1].map(r=>`<line x1="${{L}}" x2="${{W-R}}" y1="${{y(hi-range*r)}}" y2="${{y(hi-range*r)}}" stroke="#292929"/>`).join('');
      const bars=part.map((c,i)=>{{const up=c.close>=c.open,xx=x(i),top=Math.min(y(c.open),y(c.close));return `<line x1="${{xx}}" x2="${{xx}}" y1="${{y(c.high)}}" y2="${{y(c.low)}}" stroke="${{up?'#41d392':'#ff6b81'}}"/><rect x="${{xx-step*.28}}" y="${{top}}" width="${{Math.max(2,step*.56)}}" height="${{Math.max(1,Math.abs(y(c.open)-y(c.close)))}}" fill="${{up?'#41d392':'#ff6b81'}}"/>`;}}).join('');
      const nearest=time=>all.reduce((best,c,i)=>Math.abs(+new Date(c.timestamp_utc)-time)<Math.abs(+new Date(all[best].timestamp_utc)-time)?i:best,0), firstTime=+new Date(all[0].timestamp_utc), lastTime=+new Date(all.at(-1).timestamp_utc), marks=[];
      for(const trade of (chartData.trades||[])) {{ const entryTime=+new Date(trade.opened_at_utc); if(entryTime>=firstTime&&entryTime<=lastTime) {{const ei=nearest(entryTime);if(ei>=start&&ei<end) {{const xx=x(ei-start),yy=y(+trade.entry_price),fill=trade.side==='buy'?'#41d392':'#ff6b81';marks.push(`<polygon points="${{xx}},${{yy-9}} ${{xx+9}},${{yy}} ${{xx}},${{yy+9}} ${{xx-9}},${{yy}}" fill="${{fill}}"><title>Entrada simulada ${{trade.side}} em ${{Number(trade.entry_price).toFixed(priceDigits)}}</title></polygon>`);}}}} if(trade.closed_at_utc&&trade.exit_price!==null) {{const closeTime=+new Date(trade.closed_at_utc);if(closeTime>=firstTime&&closeTime<=lastTime) {{const ci=nearest(closeTime);if(ci>=start&&ci<end) {{const xx=x(ci-start),yy=y(+trade.exit_price);marks.push(`<circle cx="${{xx}}" cy="${{yy}}" r="6" fill="#000" stroke="#f6c667" stroke-width="3"><title>Saída simulada em ${{Number(trade.exit_price).toFixed(priceDigits)}}</title></circle>`);}}}}}} }}
      svg.innerHTML=grid+bars+marks.join(''); svg.hidden=false; empty.hidden=true; const timeline=document.getElementById('chart-timeline'); timeline.max=Math.max(0,all.length-visible); timeline.value=all.length-end;
    }}
    async function loadPage() {{ try {{ document.getElementById('period-label').textContent='Calculando...'; chartData=await fetchData(); end=0; renderSummary(chartData); renderChart(); }} catch(error) {{ document.getElementById('period-label').textContent=error.message; document.getElementById('market-chart-empty').textContent=error.message; }} }}
    document.getElementById('result-mode').onchange=loadPage; document.getElementById('replay-days').onchange=loadPage; document.getElementById('chart-timeframe').onchange=()=>{{end=0;renderChart();}}; document.getElementById('chart-reset').onclick=()=>{{end=0;visible=120;renderChart();}};
    document.getElementById('chart-timeline').oninput=event=>{{end=groupedCandles().length-(+event.target.value);renderChart();}}; document.getElementById('market-chart').onwheel=event=>{{event.preventDefault();visible=Math.max(12,Math.min(240,visible+(event.deltaY>0?12:-12)));renderChart();}};
    loadPage();
    </script>""")
